code_sketch:
pipeline = File.foreach('orders.txt').lazy        # lazy, line by line
  .reject { |line| line.start_with?('#') }
  .filter_map { |line| Order.parse(line) }         # drops nils too
  .select { |order| order.total.positive? }

pipeline.each { |order| sink.write(order) }         # forces the chain once

